PRAGMA foreign_keys=ON;
CREATE TABLE meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE datasets(dataset_id TEXT PRIMARY KEY,dataset_sha256 TEXT NOT NULL UNIQUE,snapshot_file TEXT NOT NULL,snapshot_sha256 TEXT NOT NULL,dataset_json TEXT NOT NULL);
CREATE TABLE queries(query_id TEXT NOT NULL,version INTEGER NOT NULL,query_sha256 TEXT NOT NULL UNIQUE,parent_sha256 TEXT,definition_json TEXT NOT NULL,PRIMARY KEY(query_id,version));
CREATE TABLE reports(report_id TEXT NOT NULL,version INTEGER NOT NULL,report_sha256 TEXT NOT NULL UNIQUE,parent_sha256 TEXT,definition_json TEXT NOT NULL,PRIMARY KEY(report_id,version));
CREATE TABLE artifacts(artifact_id TEXT PRIMARY KEY,kind TEXT NOT NULL,artifact_sha256 TEXT NOT NULL UNIQUE,payload_json TEXT NOT NULL);
CREATE TABLE reviews(artifact_sha256 TEXT NOT NULL REFERENCES artifacts(artifact_sha256),row_version INTEGER NOT NULL CHECK(row_version>0),payload_json TEXT NOT NULL,PRIMARY KEY(artifact_sha256,row_version));
CREATE TRIGGER datasets_no_update BEFORE UPDATE ON datasets BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER datasets_no_delete BEFORE DELETE ON datasets BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER queries_no_update BEFORE UPDATE ON queries BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER queries_no_delete BEFORE DELETE ON queries BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER reports_no_update BEFORE UPDATE ON reports BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER reports_no_delete BEFORE DELETE ON reports BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER artifacts_no_update BEFORE UPDATE ON artifacts BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER artifacts_no_delete BEFORE DELETE ON artifacts BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER reviews_no_update BEFORE UPDATE ON reviews BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER reviews_no_delete BEFORE DELETE ON reviews BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
